css:
@page {
    size: 80mm auto;
    margin: 0;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body,
.print-format {
    font-size: 12px;
    line-height: 1.4;
    color: #1a1a1a;
    background: #fff;
    width: 72mm;
    margin: 0 auto;
    padding: 3mm;
}

.receipt-container {
    width: 100%;
    padding: 0;
}

.receipt-header {
    text-align: center;
    padding-bottom: 6px;
    border-bottom: 2px solid #000;
}

.store-name {
    font-size: 18px;
    font-weight: 900;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    margin-bottom: 2px;
}

.store-detail {
    font-size: 9px;
    color: #000;
    line-height: 1.55;
}

.store-tax-id {
    font-size: 9px;
    font-weight: 700;
    color: #000;
    margin-top: 2px;
}

.return-banner {
    text-align: center;
    font-size: 16px;
    font-weight: 900;
    letter-spacing: 3px;
    text-transform: uppercase;
    padding: 6px 0;
    margin: 6px 0;
    border: 3px double #000;
}

.div-dashed {
    border: none;
    border-top: 1px dashed #555;
    margin: 5px 0;
}

.div-solid {
    border: none;
    border-top: 1px solid #000;
    margin: 5px 0;
}

.div-double {
    border: none;
    border-top: 3px double #000;
    margin: 5px 0;
}

.invoice-meta {
    font-size: 10px;
    padding: 4px 0;
}

.meta-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
}

.meta-label {
    color: #000;
    font-weight: 600;
}

.meta-value {
    font-weight: 600;
    text-align: right;
}

.invoice-number {
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.5px;
}

.items-header {
    display: flex;
    justify-content: space-between;
    font-size: 9px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 3px 0;
    border-bottom: 1px solid #000;
    color: #000;
}

.items-header .col-desc {
    flex: 1;
}

.items-header .col-qty {
    width: 32px;
    text-align: center;
}

.items-header .col-rate {
    width: 52px;
    text-align: right;
}

.items-header .col-amt {
    width: 60px;
    text-align: right;
}

.item-row {
    padding: 3px 0;
    border-bottom: 1px dotted #999;
}

.item-row:last-child {
    border-bottom: none;
}

.item-name {
    font-size: 11px;
    font-weight: 700;
    margin-bottom: 1px;
    word-break: break-word;
}

.item-detail-line {
    display: flex;
    justify-content: space-between;
    font-size: 10px;
    color: #000;
}

.item-detail-line .col-qty {
    width: 32px;
    text-align: center;
}

.item-detail-line .col-rate {
    width: 52px;
    text-align: right;
}

.item-detail-line .col-amt {
    width: 60px;
    text-align: right;
    font-weight: 700;
}

.item-extras {
    font-size: 9px;
    color: #333;
    padding-left: 6px;
}

.item-discount {
    font-size: 9px;
    color: #c0392b;
    padding-left: 6px;
}

.totals-section {
    padding: 4px 0 2px;
}

.total-row {
    display: flex;
    justify-content: space-between;
    font-size: 10px;
    padding: 1px 0;
}

.total-row.highlight {
    font-size: 14px;
    font-weight: 900;
    padding: 4px 0;
    letter-spacing: 0.5px;
}

.total-label {
    color: #000;
}

.total-value {
    font-weight: 700;
    text-align: right;
}

.total-row.discount .total-value {
    color: #c0392b;
}

.total-row.tax .total-label {
    font-size: 9px;
    color: #000;
}

.payments-section {
    padding: 2px 0;
}

.payment-row {
    display: flex;
    justify-content: space-between;
    font-size: 10px;
    padding: 1px 0;
}

.change-row {
    font-weight: 900;
    font-size: 12px;
}

.customer-section {
    font-size: 9px;
    padding: 3px 0;
    color: #000;
}

.customer-name {
    font-weight: 700;
    font-size: 10px;
    color: #222;
}

.return-info {
    text-align: center;
    font-size: 9px;
    color: #c0392b;
    font-weight: 700;
    padding: 3px 0;
}

.barcode-section {
    text-align: center;
    padding: 6px 0 2px;
}

.barcode-section .invoice-barcode {
    font-family: 'Libre Barcode 39', 'Courier New', monospace;
    font-size: 30px;
    letter-spacing: 2px;
    display: block;
    margin: 0 auto;
    line-height: 1;
}

.barcode-section .invoice-id-text {
    font-size: 8px;
    color: #333;
    margin-top: 2px;
}

.receipt-footer {
    text-align: center;
    padding-top: 5px;
    border-top: 2px solid #000;
}

.thank-you {
    font-size: 13px;
    font-weight: 900;
    letter-spacing: 2px;
    text-transform: uppercase;
    margin-bottom: 4px;
}

.footer-msg {
    font-size: 8px;
    line-height: 1.5;
    color: #333;
}

.footer-policy {
    font-size: 7.5px;
    color: #333;
    margin-top: 4px;
    line-height: 1.45;
}

.powered-by {
    font-size: 7px;
    margin-top: 6px;
    letter-spacing: 0.5px;
}

.receipt-header-html,
.receipt-footer-html {
    font-size: 9px;
    line-height: 1.4;
    margin: 4px 0;
}

.receipt-header-html p,
.receipt-footer-html p {
    margin: 0;
}

.header-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 4px;
}

.store-logo-left {
    max-height: 42px;
    max-width: 42px;
    border-radius: 6px;
}

.store-name-right {
    flex: 1;
    text-align: right;
    font-size: 16px;
    font-weight: 900;
    letter-spacing: 1px;
    text-transform: uppercase;
    padding-left: 6px;
    word-break: break-word;
}

@media print {

    body,
    .print-format {
        width: 72mm;
        margin: 0;
        padding: 2mm;
    }

    .page-break {
        display: none;
    }
}

html:
{% set company_doc = frappe.get_doc("Company", doc.company) %}
{% set pos_profile = frappe.get_doc("POS Profile", doc.pos_profile) %}
{% set company_name = company_doc.company_name or doc.company %}
{% set company_phone = company_doc.phone_no or "" %}
{% set company_email = company_doc.email or "" %}
{% set company_website = company_doc.website or "" %}
{% set company_address = "" %}
{% if company_doc.get("company_address") %}
{% set addr = frappe.get_doc("Address", company_doc.company_address) %}
{% set company_address = [addr.address_line1 or "", addr.address_line2 or "", addr.city or "", addr.state or "",
addr.pincode or ""] | select | join(", ") %}
{% endif %}
{% set company_tax_id = company_doc.tax_id or "" %}
{% set currency = doc.currency or frappe.db.get_value("Company", doc.company, "default_currency") or "USD" %}
{% set is_return = doc.get("is_return") or (doc.get("grand_total") and doc.grand_total < 0) %}
{% set receipt_header = company_doc.receipt_header or "" %}
{% set receipt_footer = company_doc.receipt_footer or "" %}

<div class="receipt-container">
    <div class="receipt-header">
        <div class="header-top">
        {% if company_doc.get("company_logo") %}
            <img class="store-logo-left" src="{{ company_doc.company_logo }}" alt="{{ company_name }}" />
        {% endif %}
    
            <div class="store-name-right">
                {{ company_name }}
            </div>
        </div>
        {% if receipt_header %}
            <div class="receipt-header-html">
                {{ receipt_header }}
            </div>
        {% endif %}
        <div class="store-detail">
            {% if company_address %}{{ company_address }}<br>{% endif %}
            {% if company_phone %}Tel: {{ company_phone }}{% endif %}
            {% if company_phone and company_email %} &bull; {% endif %}
            {% if company_email %}{{ company_email }}{% endif %}
            {% if company_website %}<br>{{ company_website }}{% endif %}
        </div>
        {% if company_tax_id %}
        <div class="store-tax-id">Tax ID: {{ company_tax_id }}</div>
        {% endif %}
    </div>

    {% if is_return %}
    <div class="return-banner">&#x21A9; RETURN / REFUND</div>
    {% endif %}

    <hr class="div-dashed">

    <div class="invoice-meta">
        <div class="meta-row">
            <span class="meta-label">Invoice:</span>
            <span class="meta-value invoice-number">{{ doc.name }}</span>
        </div>
        <div class="meta-row">
            <span class="meta-label">Date:</span>
            <span class="meta-value">{{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }} {{ frappe.utils.format_time(doc.posting_time, "hh:mm a") }}</span>
        </div>
        {% if doc.pos_profile %}
        <div class="meta-row">
            <span class="meta-label">Terminal:</span>
            <span class="meta-value">{{ doc.pos_profile }} - ({{ doc.set_warehouse }})</span>
        </div>
        {% endif %}
        {% if doc.get("owner") %}
        <div class="meta-row">
            <span class="meta-label">Cashier:</span>
            <span class="meta-value">{{ frappe.db.get_value("User", doc.owner, "full_name") or doc.owner
                }}</span>
        </div>
        {% endif %}
        {% if is_return and doc.get("return_against") %}
        <div class="meta-row return-info" style="text-align:left;">
            <span class="meta-label">Against:</span>
            <span class="meta-value">{{ doc.return_against }}</span>
        </div>
        {% endif %}
    </div>

    {% if doc.customer and doc.customer_name %}
    <div class="customer-section">
        <div class="meta-row">
            <span class="meta-label">Customer:</span>
            <span class="customer-name">{{ doc.customer_name }}</span>
        </div>
        {% if doc.get("contact_mobile") or doc.get("contact_phone") %}
        <div class="meta-row">
            <span class="meta-label">Phone:</span>
            <span class="meta-value">{{ doc.contact_mobile or doc.contact_phone }}</span>
        </div>
        {% endif %}
        {% if doc.get("tax_id") %}
        <div class="meta-row">
            <span class="meta-label">Tax ID:</span>
            <span class="meta-value">{{ doc.tax_id }}</span>
        </div>
        {% endif %}
    </div>
    {% endif %}

    <hr class="div-solid">

    <div class="items-header">
        <span class="col-desc">Item</span>
        <span class="col-qty">Qty</span>
        <span class="col-rate">Price</span>
        <span class="col-amt">Total</span>
    </div>

    {% for item in doc.items %}
    <div class="item-row">
        <div class="item-name">{{ item.get("local_item_name", None) or item.get("item_name") }}</div>
        {% if item.get("xpos_gift_card") %}
        <div style="font-size:9px;color:#333;">{{ xpos_gift_card_line(item) }}</div>
        {% endif %}
        <div class="item-detail-line">
            <span class="col-desc" style="flex:1;">
                {% if item.item_code != item.item_name %}
                <span style="font-size:9px;color:#333;font-weight:600;">{{ item.item_code }}</span>
                {% endif %}
            </span>
            <span class="col-qty">{{ xpos_qty(item.qty) }}</span>
            <span class="col-rate">{{ xpos_number(item.rate) }}</span>
            <span class="col-amt">{{ xpos_number(item.amount) }}</span>
        </div>
        {% if item.uom and item.uom != "Nos" and item.uom != "Unit" %}
        <div class="item-extras">UOM: {{ item.uom }}{% if item.conversion_factor and item.conversion_factor != 1 %}
            (×{{ xpos_qty(item.conversion_factor) }}){% endif %}</div>
        {% endif %}
        {% if item.serial_no %}
        <div class="item-extras">S/N: {{ item.serial_no }}</div>
        {% endif %}
        {% if item.batch_no %}
        <div class="item-extras">Batch: {{ item.batch_no }}</div>
        {% endif %}
        {% if item.discount_percentage and item.discount_percentage > 0 %}
        {% if pos_profile.get("print_discount_amount") %}
        <div class="item-discount">Discount: {{ frappe.utils.fmt_money(item.discount_amount or ((item.price_list_rate or item.rate) * item.qty * item.discount_percentage / 100), currency=currency) }}</div>
        {% else %}
        <div class="item-discount">Discount: {{ xpos_number(item.discount_percentage) }}%</div>
        {% endif %}
        {% elif item.discount_amount and item.discount_amount > 0 %}
        <div class="item-discount">Discount: {{ frappe.utils.fmt_money(item.discount_amount, currency=currency) }}</div>
        {% endif %}
        {% if item.get("pos_notes") %}
        <div class="item-extras" style="font-style:italic;">&#9998; {{ item.pos_notes }}</div>
        {% endif %}
    </div>
    {% endfor %}

    <hr class="div-double">

    <div class="totals-section">
        {% set _rd = {"v": 0} %}
        {% for item in doc.items %}
        {% if item.price_list_rate and item.price_list_rate > item.rate %}
        {% set _ = _rd.update({"v": _rd.v + (item.price_list_rate - item.rate) * item.qty}) %}
        {% endif %}
        {% endfor %}
        {% set total_discount_amount = _rd.v + (doc.discount_amount or 0) %}
        {% set _subtotal = doc.total or doc.net_total or 1 %}
        {% set total_discount_pct = (total_discount_amount / _subtotal * 100) if _subtotal else 0 %}

        {% set total_items = doc.items | length %}
        {% set total_qty = doc.total_qty or (doc.items | sum(attribute='qty')) %}
        <div class="total-row" style="font-size:9px;color:#333;">
            <span class="total-label">{{ total_items }} item{{ 's' if total_items != 1 else '' }} &bull; {{
                xpos_qty(total_qty) }} unit{{ 's' if total_qty != 1 else '' }}</span>
        </div>

        <div class="total-row">
            <span class="total-label">Subtotal</span>
            <span class="total-value">
                {{ frappe.utils.fmt_money(doc.total or doc.net_total, currency=currency) }}
            </span>
        </div>

        {% if _rd.v > 0.001 %}
        <div class="total-row discount">
            <span class="total-label">Items Discount</span>
            <span class="total-value">-{{ frappe.utils.fmt_money(_rd.v, currency=currency) }}</span>
        </div>
        {% endif %}

        {% if doc.discount_amount and doc.discount_amount > 0 %}
        <div class="total-row discount">
            <span class="total-label">
                Additional Discount
                {% if doc.additional_discount_percentage and not pos_profile.get("print_discount_amount") %} 
                    ({{ doc.additional_discount_percentage }})
                {% endif %}
            </span>
            <span class="total-value">-{{ frappe.utils.fmt_money(doc.discount_amount, currency=currency) }}</span>
        </div>
        {% endif %}

        {% if doc.net_total != doc.total %}
        <div class="total-row">
            <span class="total-label">Net Total</span>
            <span class="total-value">{{ frappe.utils.fmt_money(doc.net_total, currency=currency) }}</span>
        </div>
        {% endif %}

        {% for tax in doc.taxes %}
        <div class="total-row tax">
            <span class="total-label">
                {{ tax.description or "Tax" }}
                {% if tax.rate %} ({{ tax.rate }}%){% endif %}
                {% if tax.included_in_print_rate %} <span style="font-size:7px;">Incl.</span>{% endif %}
            </span>
            <span class="total-value">{{ frappe.utils.fmt_money(tax.tax_amount, currency=currency) }}</span>
        </div>
        {% endfor %}

        {% if doc.get("write_off_amount") and doc.write_off_amount > 0 %}
        <div class="total-row">
            <span class="total-label">Write Off</span>
            <span class="total-value">-{{ frappe.utils.fmt_money(doc.write_off_amount, currency=currency) }}</span>
        </div>
        {% endif %}

        {% if doc.get("rounding_adjustment") and doc.rounding_adjustment != 0 %}
        <div class="total-row" style="font-size:9px;">
            <span class="total-label">Rounding</span>
            <span class="total-value">{{ frappe.utils.fmt_money(doc.rounding_adjustment, currency=currency)
                }}</span>
        </div>
        {% endif %}

        {% if total_discount_amount > 0.001 %}
        <div class="total-row discount">
            <span class="total-label">
                Total Discount
                {% if not pos_profile.get("print_discount_amount") and total_discount_pct > 0 %}
                ({{ "%.1f" | format(total_discount_pct) }}%)
                {% endif %}
            </span>
            <span class="total-value">-{{ frappe.utils.fmt_money(total_discount_amount, currency=currency) }}</span>
        </div>
        {% endif %}

        <hr class="div-solid">

        <div class="total-row highlight">
            <span class="total-label">{{ "REFUND" if is_return else "TOTAL" }}</span>
            <span class="total-value">{{ frappe.utils.fmt_money((doc.rounded_total or doc.grand_total) | abs,
                currency=currency) }}</span>
        </div>
    </div>

    {% if doc.payments and doc.payments | length > 0 %}
    <hr class="div-dashed">
    <div class="payments-section">
        <div class="total-row"
            style="font-size:9px;font-weight:700;text-transform:uppercase;color:#000;margin-bottom:2px;">
            <span>Payment Details</span>
        </div>
        {% for payment in doc.payments %}
        {% if payment.amount and payment.amount != 0 %}
        {% set tender_currency = payment.get("pos_tender_currency") %}
        {% set is_foreign_tender = tender_currency and tender_currency != currency %}
        <div class="payment-row">
            <span>{{ payment.mode_of_payment }}</span>
            <span style="font-weight:700;">
                {% if is_foreign_tender %}
                {{ frappe.utils.fmt_money(payment.get("pos_tender_amount") | abs, currency=tender_currency) }}
                {% else %}
                {{ frappe.utils.fmt_money(payment.amount | abs, currency=currency) }}
                {% endif %}
            </span>
        </div>
        {% if payment.get("xpos_gift_card") %}
        <div class="payment-rate-line" style="font-size:8px;color:#555;padding-left:6px;">
            {{ xpos_gift_card_line(payment) }}
        </div>
        {% endif %}
        {% if is_foreign_tender %}
        <div class="payment-rate-line" style="font-size:8px;color:#555;padding-left:6px;">
            @ {{ xpos_tender_rate(payment.get("pos_exchange_rate"), currency) }} =
            {{ frappe.utils.fmt_money(payment.amount | abs, currency=currency) }}
        </div>
        {% endif %}
        {% endif %}
        {% endfor %}

        {% set change = doc.get("change_amount") or 0 %}
        {% if change > 0.01 and not is_return %}
        <hr class="div-dashed">
        {% if doc.get("pos_change_legs") %}
        <div class="total-row"
            style="font-size:9px;font-weight:700;text-transform:uppercase;color:#000;margin-bottom:2px;">
            <span>Change</span>
        </div>
        {% for leg in doc.pos_change_legs %}
        <div class="payment-row change-leg-row">
            <span>{{ leg.mode_of_payment }}</span>
            <span>{{ frappe.utils.fmt_money(leg.amount, currency=leg.currency or currency) }}</span>
        </div>
        {% endfor %}
        <div class="payment-row change-row" style="font-weight:700;">
            <span>Total Change</span>
            <span>{{ frappe.utils.fmt_money(change, currency=currency) }}</span>
        </div>
        {% else %}
        <div class="payment-row change-row">
            <span>Change</span>
            <span>{{ frappe.utils.fmt_money(change, currency=currency) }}</span>
        </div>
        {% endif %}
        {% endif %}
    </div>
    {% endif %}

    {% if doc.get("loyalty_points") and doc.loyalty_points > 0 %}
    <hr class="div-dashed">
    <div class="total-row" style="font-size:9px;">
        <span class="total-label">&#9733; Loyalty Points Earned</span>
        <span class="total-value" style="color:#8e44ad;">{{ doc.loyalty_points }}</span>
    </div>
    {% endif %}

    {% if doc.get("pos_notes") %}
    <hr class="div-dashed">
    <div style="font-size:9px;color:#000;padding:2px 0;">
        <strong>Notes:</strong> {{ doc.pos_notes }}
    </div>
    {% endif %}

    <div class="barcode-section">
        <span class="invoice-barcode">{{ xpos_barcode(doc.name) }}</span>
    </div>

    <div class="receipt-footer">
        {% if is_return %}
        <div class="thank-you">Refund Processed</div>
        <div class="footer-msg">
            This receipt confirms your return has been processed.<br>
            Please retain this receipt for your records.
        </div>
        {% else %}
        <div class="thank-you">Thank You!</div>
        {% endif %}
        {% if receipt_footer %}
            <div class="receipt-footer-html">
                {{ receipt_footer }}
            </div>
        {% endif %}
        <div class="powered-by">
            Powered by XPOS &bull; {{ frappe.utils.formatdate(frappe.utils.nowdate(), "yyyy") }}
        </div>
    </div>
</div>
